sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* =====================================================
       STATE
       ===================================================== */

    c.loading = false;

    c.editing = false;

    c.saving = false;

    c.saveError = '';


    /* =====================================================
       INITIALS
       ===================================================== */

    c.makeInitials = function(name) {

        if (!name) {
            return 'ST';
        }

        name = String(name).trim();

        if (!name) {
            return 'ST';
        }

        var parts = name.split(/\s+/);

        if (parts.length === 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }

        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    };


    /* =====================================================
       INITIAL DATA
       ===================================================== */

    if (
        c.data &&
        c.data.student
    ) {

        c.data.initials =
            c.makeInitials(
                c.data.student.student_name
            );

    } else {

        c.data.initials = 'ST';

    }


    /* =====================================================
       OPEN EDIT
       ===================================================== */

    c.openEdit = function() {

        if (
            !c.data ||
            !c.data.student
        ) {
            return;
        }

        c.saveError = '';

        c.editForm = {

            student_id:
                c.data.student.student_id || '',

            student_name:
                c.data.student.student_name || '',

            email:
                c.data.student.email || '',

            phone_number:
                c.data.student.phone_number || '',

            batch:
                c.data.student.batch || '',

            branch:
                c.data.student.branch || '',

            degree:
                c.data.student.degree || '',

            cgpa:
                c.data.student.cgpa || '',

            backlogs:
                c.data.student.backlogs || 0,

            placement_status:
                c.data.student.placement_status || '',

            profile_status:
                c.data.student.profile_status || ''

        };

        c.editing = true;

    };


    /* =====================================================
       CLOSE EDIT
       ===================================================== */

    c.closeEdit = function() {

        if (c.saving) {
            return;
        }

        c.editing = false;

        c.saveError = '';

    };


    /* =====================================================
       SAVE PROFILE
       ===================================================== */

    c.saveProfile = function() {

        if (c.saving) {
            return;
        }

        c.saveError = '';


        if (
            !c.editForm.student_name ||
            !String(
                c.editForm.student_name
            ).trim()
        ) {

            c.saveError =
                'Student name cannot be empty.';

            return;

        }


        if (
            c.editForm.email &&
            String(
                c.editForm.email
            ).indexOf('@') === -1
        ) {

            c.saveError =
                'Please enter a valid email address.';

            return;

        }


        if (
            c.editForm.cgpa !== '' &&
            c.editForm.cgpa !== null &&
            c.editForm.cgpa !== undefined
        ) {

            var cgpa =
                parseFloat(
                    c.editForm.cgpa
                );

            if (
                isNaN(cgpa) ||
                cgpa < 0 ||
                cgpa > 10
            ) {

                c.saveError =
                    'CGPA must be between 0 and 10.';

                return;

            }

        }


        if (
            c.editForm.backlogs !== '' &&
            c.editForm.backlogs !== null &&
            c.editForm.backlogs !== undefined
        ) {

            var backlogs =
                parseInt(
                    c.editForm.backlogs,
                    10
                );

            if (
                isNaN(backlogs) ||
                backlogs < 0
            ) {

                c.saveError =
                    'Backlogs cannot be negative.';

                return;

            }

        }


        c.saving = true;


        c.server.get({

            action: 'save_profile',

            profile: c.editForm

        }).then(

            function(response) {

                c.saving = false;


                if (
                    response &&
                    response.data &&
                    response.data.saveSuccess
                ) {

                    c.editing = false;

                    c.loading = true;


                    c.server.refresh().then(

                        function() {

                            c.loading = false;


                            if (
                                c.data &&
                                c.data.student
                            ) {

                                c.data.initials =
                                    c.makeInitials(
                                        c.data.student.student_name
                                    );

                            }

                        },

                        function() {

                            c.loading = false;

                        }

                    );

                } else {

                    c.saveError =
                        (
                            response &&
                            response.data &&
                            response.data.saveMessage
                        ) ||
                        'Unable to save the profile.';

                }

            },

            function() {

                c.saving = false;

                c.saveError =
                    'Unable to save the profile. Please try again.';

            }

        );

    };


    /* =====================================================
       REFRESH
       ===================================================== */

    c.refresh = function() {

        if (c.loading) {
            return;
        }

        c.loading = true;


        c.server.refresh().then(

            function() {

                c.loading = false;


                if (
                    c.data &&
                    c.data.student
                ) {

                    c.data.initials =
                        c.makeInitials(
                            c.data.student.student_name
                        );

                }

            },

            function() {

                c.loading = false;

            }

        );

    };


    /* =====================================================
       DASHBOARD NAVIGATION
       ===================================================== */

    c.goToDashboard = function() {

        /*
         * Your actual student dashboard page ID.
         */

        window.location.href =
            '?id=campus360_student_dashboard';

    };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 STUDENT PROFILE
   FULL SCREEN / FULL WIDTH
   PROFESSIONAL COLORED UI
   ========================================================= */


/* =========================================================
   MAIN PROFILE PAGE
   ========================================================= */

.campus360-profile {
  width: 100vw !important;
  max-width: none !important;

  /*
   * Full-bleed Service Portal layout.
   * Removes the centered 1180px restriction.
   */
  position: relative !important;

  left: 50% !important;

  margin-left: -50vw !important;
  margin-right: -50vw !important;

  padding: 28px 32px 65px;

  min-height: 100vh;

  box-sizing: border-box;

  /* PAGE BACKGROUND */
  background:
    linear-gradient(
      135deg,
      #eef6ff 0%,
      #f6f1ff 48%,
      #eefaf6 100%
    );

  color: #172033;

  font-family:
    Arial,
    Helvetica,
    sans-serif;

  overflow-x: hidden;
}


.campus360-profile *,
.campus360-profile *::before,
.campus360-profile *::after {
  box-sizing: border-box;
}


/* =========================================================
   PROFILE HEADER
   ========================================================= */

.profile-top {
  position: relative;

  width: 100%;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  padding: 28px 30px;

  margin-bottom: 22px;

  background:
    linear-gradient(
      120deg,
      #e8ddff 0%,
      #eee8ff 32%,
      #e4f1ff 67%,
      #e5f8f0 100%
    );

  border: 1px solid #d4c9f0;

  border-radius: 20px;

  box-shadow:
    0 10px 30px rgba(67, 52, 112, .10);

  overflow: hidden;
}


/* =========================================================
   COLORFUL TOP LINE
   ========================================================= */

.profile-top::before {
  content: "";

  position: absolute;

  left: 0;

  top: 0;

  width: 100%;

  height: 5px;

  background:
    linear-gradient(
      90deg,
      #7040c8,
      #4d82d9,
      #2da878
    );
}


/* =========================================================
   STUDENT INFORMATION
   ========================================================= */

.profile-person {
  display: flex;

  align-items: center;

  gap: 18px;

  min-width: 0;

  position: relative;

  z-index: 2;
}


.profile-avatar {
  width: 78px;

  height: 78px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #eee5ff
    );

  border: 5px solid rgba(255,255,255,.9);

  color: #6337c7;

  font-size: 23px;

  font-weight: 900;

  box-shadow:
    0 6px 20px rgba(82,55,150,.20);
}


.profile-person-info {
  min-width: 0;
}


.profile-label {
  margin-bottom: 5px;

  color: #6736c4;

  font-size: 10px;

  letter-spacing: 1.7px;

  font-weight: 900;
}


.profile-person-info h1 {
  margin: 0;

  color: #111a2e;

  font-size: 28px;

  line-height: 1.25;

  font-weight: 850;
}


.profile-person-info p {
  margin: 5px 0 0;

  color: #4e6079;

  font-size: 12px;
}


.profile-course {
  margin-top: 6px;

  color: #273c57;

  font-size: 12px;

  font-weight: 800;
}


/* =========================================================
   TOP ACTION BUTTONS
   ========================================================= */

.profile-top-actions {
  position: relative;

  z-index: 3;

  display: flex;

  align-items: center;

  gap: 10px;

  flex-shrink: 0;
}


/* =========================================================
   DASHBOARD BUTTON
   BLUE
   ========================================================= */

.dashboard-button {
  height: 43px;

  padding: 0 16px;

  border-radius: 9px;

  background: #ffffff;

  border: 1px solid #78a9e5;

  color: #2463aa;

  font-size: 12px;

  font-weight: 850;

  cursor: pointer;

  box-shadow:
    0 3px 8px rgba(39,99,170,.08);

  transition:
    all .18s ease;
}


.dashboard-button:hover {
  background: #e8f2ff;

  border-color: #4386d1;

  color: #174e8c;

  transform: translateY(-1px);
}


/* =========================================================
   REFRESH BUTTON
   GREEN
   ========================================================= */

.refresh-button {
  height: 43px;

  padding: 0 16px;

  border-radius: 9px;

  background: #ffffff;

  border: 1px solid #70b99a;

  color: #237b58;

  font-size: 12px;

  font-weight: 850;

  cursor: pointer;

  box-shadow:
    0 3px 8px rgba(35,123,88,.07);

  transition:
    all .18s ease;
}


.refresh-button:hover {
  background: #e8f7f0;

  border-color: #48a47b;

  color: #176342;

  transform: translateY(-1px);
}


/* =========================================================
   EDIT PROFILE BUTTON
   PURPLE
   ========================================================= */

.edit-button {
  height: 43px;

  padding: 0 17px;

  border-radius: 9px;

  background:
    linear-gradient(
      135deg,
      #7040c8,
      #5e35b1
    );

  border: 1px solid #6337b7;

  color: #ffffff;

  font-size: 12px;

  font-weight: 850;

  cursor: pointer;

  box-shadow:
    0 6px 14px rgba(99,55,183,.23);

  transition:
    all .18s ease;
}


.edit-button:hover {
  background:
    linear-gradient(
      135deg,
      #6033b7,
      #4f299e
    );

  transform: translateY(-1px);

  box-shadow:
    0 8px 17px rgba(99,55,183,.28);
}


.dashboard-icon,
.refresh-icon,
.edit-icon {
  margin-right: 5px;

  font-size: 13px;
}


/* =========================================================
   PROFILE CONTENT
   ========================================================= */

.profile-content {
  width: 100%;

  max-width: none;
}


/* =========================================================
   COMMON SECTION
   ========================================================= */

.profile-section {
  position: relative;

  width: 100%;

  margin-bottom: 21px;

  padding: 27px;

  border-radius: 19px;

  box-sizing: border-box;

  box-shadow:
    0 7px 22px rgba(35,48,75,.055);

  overflow: hidden;

  transition:
    transform .18s ease,
    box-shadow .18s ease;
}


.profile-section:hover {
  transform: translateY(-1px);

  box-shadow:
    0 10px 28px rgba(35,48,75,.09);
}


/* =========================================================
   PERSONAL
   BLUE
   ========================================================= */

.personal-section {
  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #f1f7ff 100%
    );

  border: 1px solid #c5dbf5;
}


.personal-section::before {
  content: "";

  position: absolute;

  left: 0;

  top: 0;

  width: 5px;

  height: 100%;

  background:
    linear-gradient(
      180deg,
      #3478d4,
      #63a0eb
    );
}


/* =========================================================
   ACADEMICS
   ORANGE / GOLD
   ========================================================= */

.academic-section {
  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #fff8e9 100%
    );

  border: 1px solid #efd8a3;
}


.academic-section::before {
  content: "";

  position: absolute;

  left: 0;

  top: 0;

  width: 5px;

  height: 100%;

  background:
    linear-gradient(
      180deg,
      #d99420,
      #edb94f
    );
}


/* =========================================================
   PLACEMENT
   GREEN
   ========================================================= */

.placement-section {
  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #effaf5 100%
    );

  border: 1px solid #c6e6d4;
}


.placement-section::before {
  content: "";

  position: absolute;

  left: 0;

  top: 0;

  width: 5px;

  height: 100%;

  background:
    linear-gradient(
      180deg,
      #299967,
      #5ac08d
    );
}


/* =========================================================
   RESUME
   ROSE
   ========================================================= */

.resume-section {
  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #fff5f6 100%
    );

  border: 1px solid #edcdd1;
}


.resume-section::before {
  content: "";

  position: absolute;

  left: 0;

  top: 0;

  width: 5px;

  height: 100%;

  background:
    linear-gradient(
      180deg,
      #bd5661,
      #df7b83
    );
}


/* =========================================================
   SECTION HEADINGS
   ========================================================= */

.section-heading {
  display: flex;

  justify-content: space-between;

  align-items: flex-start;

  margin-bottom: 22px;
}


.section-label {
  margin-bottom: 5px;

  font-size: 10px;

  letter-spacing: 1.3px;

  font-weight: 900;
}


.personal-label {
  color: #2866b8;
}


.academic-label {
  color: #ad6c08;
}


.placement-label {
  color: #198051;
}


.resume-label {
  color: #a9414c;
}


.section-heading h2 {
  margin: 0;

  color: #111c31;

  font-size: 22px;

  font-weight: 800;
}


.section-heading p {
  margin: 5px 0 0;

  color: #62718a;

  font-size: 12px;
}


.section-icon {
  width: 44px;

  height: 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 12px;

  font-size: 17px;

  font-weight: 900;
}


.personal-icon {
  background: #e5f0ff;

  border: 1px solid #c4daf8;

  color: #286bc2;
}


.academic-icon {
  background: #fff0cc;

  border: 1px solid #efd18d;

  color: #b87308;
}


.placement-icon {
  background: #e1f6ea;

  border: 1px solid #bfe4cf;

  color: #198051;
}


.resume-icon {
  background: #fbe7e9;

  border: 1px solid #edc7cc;

  color: #ad3e49;
}


/* =========================================================
   PERSONAL INFORMATION CARDS
   ========================================================= */

.information-grid {
  width: 100%;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 14px 17px;
}


.information-field {
  min-height: 76px;

  padding: 16px 18px;

  box-sizing: border-box;

  background: rgba(255,255,255,.88);

  border: 1px solid #d5e2f1;

  border-radius: 12px;

  transition:
    border-color .18s ease,
    transform .18s ease,
    box-shadow .18s ease;
}


.information-field:hover {
  border-color: #8bb6e6;

  box-shadow:
    0 4px 12px rgba(45,102,180,.07);

  transform: translateY(-1px);
}


.information-field label,
.academic-field label,
.placement-field label {
  display: block;

  margin-bottom: 8px;

  color: #75849b;

  font-size: 9px;

  letter-spacing: 1px;

  font-weight: 900;
}


.field-value {
  color: #101c31;

  font-size: 14px;

  line-height: 1.4;

  font-weight: 750;

  word-break: break-word;
}


/* =========================================================
   ACADEMIC CARDS
   ========================================================= */

.academic-information-grid {
  width: 100%;

  display: grid;

  grid-template-columns:
    repeat(5, minmax(0, 1fr));

  gap: 12px;
}


.academic-field {
  min-height: 85px;

  padding: 16px;

  border-radius: 12px;

  background: #ffffff;

  border: 1px solid #e5e7eb;
}


.degree-field {
  border-top: 4px solid #4389df;

  background: #f3f8ff;
}


.branch-field {
  border-top: 4px solid #d46a9a;

  background: #fff4f9;
}


.batch-field {
  border-top: 4px solid #36a18b;

  background: #f0faf7;
}


.cgpa-field {
  border-top: 4px solid #df9b37;

  background: #fff8eb;
}


.backlog-field {
  border-top: 4px solid #d76870;

  background: #fff5f6;
}


.academic-value {
  color: #172136;

  font-size: 14px;

  font-weight: 800;

  line-height: 1.4;

  word-break: break-word;
}


/* =========================================================
   PLACEMENT
   ========================================================= */

.placement-information-grid {
  width: 100%;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 14px;
}


.placement-field {
  min-height: 77px;

  padding: 16px 18px;

  background: rgba(255,255,255,.88);

  border: 1px solid #cfe5d9;

  border-radius: 12px;
}


.placement-value {
  display: flex;

  align-items: center;

  gap: 8px;

  color: #214634;

  font-size: 14px;

  font-weight: 800;
}


.status-dot {
  width: 9px;

  height: 9px;

  display: inline-block;

  border-radius: 50%;

  background: #e0a327;
}


.status-dot.placed,
.active-dot {
  background: #24955f;

  box-shadow:
    0 0 0 3px rgba(36,149,95,.12);
}


/* =========================================================
   RESUME
   ========================================================= */

.resume-box {
  width: 100%;

  display: flex;

  align-items: center;

  gap: 14px;

  padding: 17px;

  background: rgba(255,255,255,.88);

  border: 1px solid #ead9dc;

  border-radius: 12px;
}


.resume-symbol {
  width: 45px;

  height: 45px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 10px;

  background: #f4dfe2;

  color: #a83d48;

  font-size: 10px;

  font-weight: 900;
}


.resume-text {
  flex: 1;

  min-width: 0;
}


.resume-text strong {
  display: block;

  color: #263144;

  font-size: 13px;

  font-weight: 800;
}


.resume-text span {
  display: block;

  margin-top: 4px;

  color: #748094;

  font-size: 11px;
}


.resume-status {
  padding: 7px 12px;

  border-radius: 16px;

  background: #e1f5e9;

  border: 1px solid #bce2cb;

  color: #177747;

  font-size: 10px;

  font-weight: 900;
}


.resume-empty {
  background: rgba(255,255,255,.72);

  border-style: dashed;
}


.empty-symbol {
  background: #eef0f4;

  color: #697586;
}


/* =========================================================
   INFORMATION NOTE
   ========================================================= */

.profile-information-note {
  width: 100%;

  display: flex;

  align-items: center;

  gap: 11px;

  padding: 15px 17px;

  margin-top: 3px;

  background:
    linear-gradient(
      135deg,
      #f1f4ff,
      #f7f5ff
    );

  border: 1px solid #d7def7;

  border-radius: 12px;
}


.note-symbol {
  width: 28px;

  height: 28px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  background: #6874d8;

  color: #ffffff;

  font-size: 11px;

  font-weight: 900;
}


.profile-information-note strong {
  display: block;

  color: #3f498d;

  font-size: 11px;
}


.profile-information-note p {
  margin: 3px 0 0;

  color: #69749b;

  font-size: 10px;
}


/* =========================================================
   LOADING
   ========================================================= */

.profile-loading {
  min-height: 260px;

  width: 100%;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 12px;

  background: #ffffff;

  border: 1px solid #e0e5ed;

  border-radius: 18px;

  color: #64748b;

  font-size: 12px;
}


.spinner {
  width: 32px;

  height: 32px;

  border: 3px solid #e7eaf0;

  border-top-color: #7040c8;

  border-radius: 50%;

  animation:
    profileSpin .8s linear infinite;
}


@keyframes profileSpin {

  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }

}


/* =========================================================
   ERROR
   ========================================================= */

.profile-error {
  width: 100%;

  display: flex;

  align-items: center;

  gap: 13px;

  padding: 20px;

  background: #fff6f7;

  border: 1px solid #efc9cd;

  border-radius: 13px;

  color: #9f313b;
}


.error-icon {
  width: 34px;

  height: 34px;

  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  background: #f8dfe2;

  color: #ad3039;

  font-weight: 900;
}


.profile-error strong {
  font-size: 13px;
}


.profile-error p {
  margin: 3px 0 0;

  color: #806067;

  font-size: 11px;
}


/* =========================================================
   EDIT PROFILE MODAL
   ========================================================= */

.edit-modal-overlay {
  position: fixed;

  z-index: 99999;

  top: 0;

  left: 0;

  right: 0;

  bottom: 0;

  display: flex;

  align-items: center;

  justify-content: center;

  padding: 20px;

  box-sizing: border-box;

  background: rgba(15,23,42,.58);

  backdrop-filter: blur(3px);
}


.edit-modal {
  width: 100%;

  max-width: 820px;

  max-height: 92vh;

  display: flex;

  flex-direction: column;

  background: #ffffff;

  border-radius: 17px;

  overflow: hidden;

  box-shadow:
    0 25px 70px rgba(15,23,42,.25);
}


.edit-modal-header {
  display: flex;

  justify-content: space-between;

  align-items: flex-start;

  gap: 15px;

  padding: 22px 25px;

  background:
    linear-gradient(
      135deg,
      #ffffff,
      #f8f5ff
    );

  border-bottom: 1px solid #e5e9f0;
}


.modal-label {
  margin-bottom: 4px;

  color: #7040c8;

  font-size: 9px;

  letter-spacing: 1.4px;

  font-weight: 900;
}


.edit-modal-header h2 {
  margin: 0;

  color: #182234;

  font-size: 21px;

  font-weight: 800;
}


.edit-modal-header p {
  margin: 5px 0 0;

  color: #697586;

  font-size: 11px;
}


.modal-close {
  width: 34px;

  height: 34px;

  border: 1px solid #dce1e8;

  border-radius: 8px;

  background: #ffffff;

  color: #64748b;

  font-size: 22px;

  cursor: pointer;
}


.modal-close:hover {
  background: #f5f6f8;

  color: #1f2937;
}


.edit-modal-content {
  overflow-y: auto;

  padding: 23px 25px;
}


.edit-group {
  margin-bottom: 24px;
}


.edit-group:last-child {
  margin-bottom: 0;
}


.edit-group-heading {
  display: flex;

  align-items: center;

  gap: 10px;

  padding-bottom: 10px;

  margin-bottom: 15px;

  border-bottom: 1px solid #e8ebf0;
}


.group-number {
  width: 29px;

  height: 29px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 8px;

  background: #eee8ff;

  color: #6b3fc1;

  font-size: 9px;

  font-weight: 900;
}


.academic-number {
  background: #fff2d5;

  color: #ad6b0c;
}


.placement-number {
  background: #e4f6ec;

  color: #177a4a;
}


.edit-group-heading strong {
  display: block;

  color: #273142;

  font-size: 12px;

  font-weight: 900;
}


.edit-group-heading small {
  display: block;

  margin-top: 2px;

  color: #7a8495;

  font-size: 10px;
}


.edit-fields {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 14px;
}


.edit-field label {
  display: block;

  margin-bottom: 6px;

  color: #475467;

  font-size: 10px;

  font-weight: 800;
}


.edit-field input,
.edit-field select {
  width: 100%;

  height: 41px;

  padding: 0 11px;

  box-sizing: border-box;

  background: #fbfcfd;

  border: 1px solid #d4dae3;

  border-radius: 8px;

  color: #1d2939;

  font-size: 12px;

  font-weight: 600;

  outline: none;
}


.edit-field input:focus,
.edit-field select:focus {
  background: #ffffff;

  border-color: #7950ca;

  box-shadow:
    0 0 0 3px rgba(121,80,202,.10);
}


.edit-field input:disabled {
  background: #f1f3f6;

  color: #7a8495;

  cursor: not-allowed;
}


.save-error {
  margin-top: 15px;

  padding: 10px 12px;

  background: #fff1f2;

  border: 1px solid #efc4c8;

  border-radius: 8px;

  color: #ad3039;

  font-size: 11px;

  font-weight: 700;
}


/* =========================================================
   EDIT MODAL FOOTER
   ========================================================= */

.edit-modal-footer {
  display: flex;

  justify-content: flex-end;

  gap: 9px;

  padding: 15px 25px;

  background: #fafbfc;

  border-top: 1px solid #e4e8ee;
}


.cancel-button,
.save-button {
  height: 39px;

  padding: 0 17px;

  border-radius: 8px;

  font-size: 11px;

  font-weight: 800;

  cursor: pointer;
}


.cancel-button {
  background: #ffffff;

  border: 1px solid #d2d8e1;

  color: #475467;
}


.save-button {
  background:
    linear-gradient(
      135deg,
      #7040c8,
      #6035b4
    );

  border: 1px solid #7040c8;

  color: #ffffff;

  box-shadow:
    0 4px 10px rgba(109,63,194,.16);
}


.save-button:hover {
  background:
    linear-gradient(
      135deg,
      #5d31ae,
      #51299f
    );
}


.cancel-button:disabled,
.save-button:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {

  .campus360-profile {
    padding-left: 24px;

    padding-right: 24px;
  }


  .academic-information-grid {
    grid-template-columns:
      repeat(4, minmax(0, 1fr));
  }

}


@media (max-width: 1050px) {

  .academic-information-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

}


@media (max-width: 850px) {

  .campus360-profile {
    padding-left: 18px;

    padding-right: 18px;
  }


  .profile-top {
    flex-direction: column;

    align-items: stretch;
  }


  .profile-top-actions {
    width: 100%;

    justify-content: flex-start;
  }


  .information-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }


  .placement-information-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }


  .academic-information-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


@media (max-width: 780px) {

  .campus360-profile {
    width: 100vw !important;

    max-width: none !important;

    position: relative !important;

    left: 50% !important;

    margin-left: -50vw !important;

    margin-right: -50vw !important;

    padding: 18px 12px 45px;
  }


  .profile-top {
    flex-direction: column;

    align-items: stretch;
  }


  .profile-top-actions {
    width: 100%;

    display: grid;

    grid-template-columns:
      repeat(3, minmax(0, 1fr));

    gap: 8px;
  }


  .dashboard-button,
  .refresh-button,
  .edit-button {
    width: 100%;

    padding-left: 8px;

    padding-right: 8px;
  }


  .information-grid,
  .placement-information-grid,
  .edit-fields {
    grid-template-columns: 1fr;
  }


  .academic-information-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }


  .profile-section {
    padding: 23px;
  }

}


@media (max-width: 620px) {

  .campus360-profile {
    padding-left: 10px;

    padding-right: 10px;
  }


  .profile-top {
    padding: 21px;
  }


  .profile-person {
    align-items: flex-start;
  }


  .profile-avatar {
    width: 62px;

    height: 62px;

    font-size: 19px;
  }


  .profile-person-info h1 {
    font-size: 23px;
  }


  .profile-top-actions {
    grid-template-columns: 1fr;
  }


  .dashboard-button,
  .refresh-button,
  .edit-button {
    width: 100%;
  }


  .profile-section {
    padding: 21px;
  }


  .academic-information-grid {
    grid-template-columns: 1fr;
  }


  .section-heading {
    gap: 15px;
  }


  .section-heading h2 {
    font-size: 20px;
  }


  .section-icon {
    width: 40px;

    height: 40px;
  }


  .resume-box {
    align-items: flex-start;

    flex-wrap: wrap;
  }


  .resume-status {
    margin-left: 59px;
  }


  .edit-modal-overlay {
    padding: 8px;
  }


  .edit-modal {
    max-height: 96vh;
  }


  .edit-modal-header,
  .edit-modal-content {
    padding-left: 19px;

    padding-right: 19px;
  }


  .edit-modal-footer {
    padding-left: 19px;

    padding-right: 19px;
  }

}


@media (max-width: 430px) {

  .campus360-profile {
    padding-left: 7px;

    padding-right: 7px;
  }


  .profile-top {
    padding: 18px;
  }


  .profile-person {
    gap: 11px;
  }


  .profile-avatar {
    width: 55px;

    height: 55px;

    border-width: 4px;

    font-size: 17px;
  }


  .profile-person-info h1 {
    font-size: 20px;
  }


  .profile-person-info p,
  .profile-course {
    font-size: 11px;
  }


  .profile-section {
    padding: 18px;
  }


  .information-field,
  .academic-field,
  .placement-field {
    padding: 14px;
  }


  .field-value,
  .academic-value,
  .placement-value {
    font-size: 13px;
  }


  .profile-information-note {
    align-items: flex-start;
  }


  .resume-status {
    margin-left: 0;

    width: 100%;

    text-align: center;
  }

}

sp_widget.script:
(function() {

    /* =====================================================
       INITIAL DATA
       ===================================================== */

    data.error = '';

    data.student = null;

    data.initials = 'ST';

    data.saveSuccess = false;

    data.saveMessage = '';

    data.choices = {

        degree: [],

        branch: [],

        placement_status: [],

        profile_status: []

    };


    /* =====================================================
       STUDENT ID
       ===================================================== */

    var studentId =
        $sp.getParameter('student') ||
        'STU_TEST_001';


    /* =====================================================
       FIND STUDENT MASTER
       ===================================================== */

    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );


    studentGR.addQuery(
        'student_id',
        studentId
    );

    studentGR.setLimit(1);

    studentGR.query();


    if (!studentGR.next()) {

        data.error =
            'Student Master record was not found for Student ID: ' +
            studentId;

        return;

    }


    /* =====================================================
       SAVE PROFILE ACTION
       ===================================================== */

    if (
        input &&
        input.action === 'save_profile'
    ) {

        saveProfile(studentGR);

        return;

    }


    /* =====================================================
       LOAD STUDENT
       ===================================================== */

    loadStudent(studentGR);


    /* =====================================================
       LOAD CHOICES
       ===================================================== */

    data.choices.degree =
        loadChoices('degree');


    data.choices.branch =
        loadChoices('branch');


    data.choices.placement_status =
        loadChoices('placement_status');


    data.choices.profile_status =
        loadChoices('profile_status');


    /* =====================================================
       LOAD STUDENT DATA
       ===================================================== */

    function loadStudent(gr) {

        var studentName =
            gr.getDisplayValue(
                'student_name'
            );


        data.student = {

            sys_id:
                gr.getUniqueValue(),

            student_id:
                gr.getDisplayValue(
                    'student_id'
                ),

            student_name:
                studentName,

            email:
                gr.getDisplayValue(
                    'email'
                ),

            phone_number:
                gr.getDisplayValue(
                    'phone_number'
                ),

            batch:
                gr.getDisplayValue(
                    'batch'
                ),

            branch:
                gr.getDisplayValue(
                    'branch'
                ),

            degree:
                gr.getDisplayValue(
                    'degree'
                ),

            cgpa:
                gr.getDisplayValue(
                    'cgpa'
                ),

            backlogs:
                gr.getDisplayValue(
                    'backlogs'
                ),

            placement_status:
                gr.getDisplayValue(
                    'placement_status'
                ),

            profile_status:
                gr.getDisplayValue(
                    'profile_status'
                ),

            has_resume:
                checkResume(gr)

        };


        data.initials =
            makeInitials(
                studentName
            );

    }


    /* =====================================================
       SAVE PROFILE
       ===================================================== */

    function saveProfile(gr) {

        if (
            !input.profile
        ) {

            data.saveMessage =
                'No profile information was received.';

            return;

        }


        var profile =
            input.profile;


        /* STUDENT NAME */

        if (
            gr.isValidField(
                'student_name'
            )
        ) {

            gr.setValue(
                'student_name',
                String(
                    profile.student_name || ''
                ).trim()
            );

        }


        /* EMAIL */

        if (
            gr.isValidField(
                'email'
            )
        ) {

            gr.setValue(
                'email',
                profile.email || ''
            );

        }


        /* PHONE */

        if (
            gr.isValidField(
                'phone_number'
            )
        ) {

            gr.setValue(
                'phone_number',
                profile.phone_number || ''
            );

        }


        /* BATCH */

        if (
            gr.isValidField(
                'batch'
            )
        ) {

            gr.setValue(
                'batch',
                profile.batch || ''
            );

        }


        /* DEGREE */

        if (
            gr.isValidField(
                'degree'
            )
        ) {

            gr.setValue(
                'degree',
                profile.degree || ''
            );

        }


        /* BRANCH */

        if (
            gr.isValidField(
                'branch'
            )
        ) {

            gr.setValue(
                'branch',
                profile.branch || ''
            );

        }


        /* CGPA */

        if (
            gr.isValidField(
                'cgpa'
            )
        ) {

            if (
                profile.cgpa === '' ||
                profile.cgpa === null ||
                profile.cgpa === undefined
            ) {

                gr.setValue(
                    'cgpa',
                    ''
                );

            } else {

                var cgpa =
                    parseFloat(
                        profile.cgpa
                    );


                if (
                    !isNaN(cgpa) &&
                    cgpa >= 0 &&
                    cgpa <= 10
                ) {

                    gr.setValue(
                        'cgpa',
                        cgpa
                    );

                }

            }

        }


        /* BACKLOGS */

        if (
            gr.isValidField(
                'backlogs'
            )
        ) {

            if (
                profile.backlogs === '' ||
                profile.backlogs === null ||
                profile.backlogs === undefined
            ) {

                gr.setValue(
                    'backlogs',
                    0
                );

            } else {

                var backlogs =
                    parseInt(
                        profile.backlogs,
                        10
                    );


                if (
                    !isNaN(backlogs) &&
                    backlogs >= 0
                ) {

                    gr.setValue(
                        'backlogs',
                        backlogs
                    );

                }

            }

        }


        /* PLACEMENT STATUS */

        if (
            gr.isValidField(
                'placement_status'
            )
        ) {

            gr.setValue(
                'placement_status',
                profile.placement_status || ''
            );

        }


        /* PROFILE STATUS */

        if (
            gr.isValidField(
                'profile_status'
            )
        ) {

            gr.setValue(
                'profile_status',
                profile.profile_status || ''
            );

        }


        /* UPDATE RECORD */

        var updatedId =
            gr.update();


        if (updatedId) {

            data.saveSuccess = true;

            data.saveMessage =
                'Profile updated successfully.';

        } else {

            data.saveSuccess = false;

            data.saveMessage =
                'The profile could not be updated.';

        }

    }


    /* =====================================================
       LOAD CHOICE VALUES
       ===================================================== */

    function loadChoices(fieldName) {

        var choices = [];


        try {

            var choiceGR =
                new GlideRecord(
                    'sys_choice'
                );


            choiceGR.addQuery(
                'name',
                'x_snc_campus360_student_master'
            );


            choiceGR.addQuery(
                'element',
                fieldName
            );


            choiceGR.addQuery(
                'inactive',
                false
            );


            choiceGR.orderBy(
                'sequence'
            );


            choiceGR.query();


            while (
                choiceGR.next()
            ) {

                choices.push({

                    value:
                        choiceGR.getValue(
                            'value'
                        ),

                    label:
                        choiceGR.getValue(
                            'label'
                        )

                });

            }

        } catch (e) {

            choices = [];

        }


        return choices;

    }


    /* =====================================================
       CHECK RESUME
       ===================================================== */

    function checkResume(gr) {

        if (
            !gr.isValidField(
                'resume'
            )
        ) {

            return false;

        }


        return !!gr.getValue(
            'resume'
        );

    }


    /* =====================================================
       MAKE INITIALS
       ===================================================== */

    function makeInitials(name) {

        if (!name) {
            return 'ST';
        }


        name =
            String(name).trim();


        if (!name) {
            return 'ST';
        }


        var parts =
            name.split(/\s+/);


        if (
            parts.length === 1
        ) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    }

})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
